import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('console', msg => console.log('console', msg.type(), msg.text()));
page.on('pageerror', err => console.log('pageerror', err.message));
await page.goto('http://127.0.0.1:3011/', { waitUntil: 'networkidle' });
console.log('buttons', await page.getByRole('button').evaluateAll(btns => btns.slice(0, 12).map(b => `${b.getAttribute('aria-label') || b.textContent}:${getComputedStyle(b).display}:${getComputedStyle(b).visibility}`)));
await page.getByRole('button', { name: 'Menu' }).click();
console.log('drawer count', await page.locator('.mobile-drawer.open').count());
await page.getByRole('button', { name: /Reveal search/ }).click();
await page.getByPlaceholder(/Search prompts/).fill('cold email');
await page.getByRole('button', { name: 'Open The Cold-Email Closer' }).click({ force: true });
console.log('dialog count', await page.getByRole('dialog').count());
await browser.close();
